begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();sa uuid;sb uuid;pid uuid:=gen_random_uuid();other uuid:=gen_random_uuid();oid uuid:=gen_random_uuid();val uuid:=gen_random_uuid();cid uuid;did uuid:=gen_random_uuid();old_id uuid:=gen_random_uuid();r jsonb;f jsonb;legacy jsonb:='{"budgetMinPaise":0,"budgetMaxPaise":10000,"giftTypeId":null,"occasionId":null,"recipient":"","message":""}';failed boolean;
begin
 insert into auth.users(id,email_confirmed_at) values(a,now()),(b,now());
 sa:=public.memocious_session_open(repeat('e',64),repeat('f',64),a,'customer','fixture','1');
 sb:=public.memocious_session_open(repeat('c',64),repeat('d',64),b,'customer','fixture','1');
 select id into cid from memocious.categories where slug='gift-hampers';
 insert into memocious.products(id,slug,name,active,publication_state,customizable,moq,lead_days,price_paise,max_price_paise) values(pid,'builder-config-fixture','Builder configuration',true,'published',true,2,3,0,1000),(other,'builder-other-fixture','Other type',true,'published',true,1,0,100,null);
 insert into memocious.product_categories(product_id,category_id) select pid,id from memocious.categories where slug='festive-hampers';
 insert into memocious.product_categories(product_id,category_id) select other,id from memocious.categories where slug='bouquets';
 insert into memocious.product_images(product_id,public_path,alt,sanitized_at,published_at) values(pid,'/media/builder.webp','Synthetic fixture',now(),now()),(other,'/media/builder-other.webp','Synthetic fixture',now(),now());
 insert into memocious.product_options(id,product_id,kind,label,required,max_count) values(oid,pid,'addon','Synthetic add-on',true,1);
 insert into memocious.option_values(id,option_id,label,delta_paise) values(val,oid,'Extra synthetic wrapping',2000);
 perform memocious_private.refresh_publication();
 execute 'set local role service_role';
 if jsonb_array_length(public.memocious_builder_choices(cid))<>1 then raise exception 'Descendant choices mismatch';end if;
 f:=legacy||jsonb_build_object('giftTypeId',cid,'productId',pid,'pricingVersion',1,'options',jsonb_build_array(val),'quantity',2,'requestedDate',((now() at time zone 'Asia/Kolkata')::date+10)::text,'contact',jsonb_build_object('name','Test','phone','447700900123','email','fixture@example.invalid','city','Test','pincode','400001'));
 r:=public.memocious_builder_draft(sa,'create',gen_random_uuid(),0,2,5,jsonb_set(f,'{options}','[]'));
 if r->'estimate'->>'minPaise'<>'0' then raise exception 'Zero estimate became absent';end if;
 r:=public.memocious_builder_draft(sa,'create',did,0,2,8,f);
 if r->'estimate'->>'minPaise'<>'4000' or r->'estimate'->>'maxPaise'<>'6000' or r->>'schemaVersion'<>'2' then raise exception 'Server estimate arithmetic failed';end if;
 if r<>public.memocious_builder_draft(sa,'create',did,0,2,8,f) then raise exception 'Schema 2 retry failed';end if;
 failed:=false;begin perform public.memocious_builder_draft(sb,'save',did,1,2,8,f);exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Other account rewrote schema 2';end if;
 failed:=false;begin perform public.memocious_builder_draft(sa,'save',did,1,2,8,jsonb_set(f,'{options}','[]'));exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Required option ignored';end if;
 failed:=false;begin perform public.memocious_builder_draft(sa,'save',did,1,2,8,jsonb_set(f,'{options}',jsonb_build_array(val,val)));exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Duplicate option accepted';end if;
 failed:=false;begin perform public.memocious_builder_draft(sa,'save',did,1,2,8,jsonb_set(f,'{productId}',to_jsonb(other)));exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Cross-type product accepted';end if;
 failed:=false;begin perform public.memocious_builder_draft(sa,'save',did,1,2,8,jsonb_set(f,'{quantity}','1'));exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'MOQ ignored';end if;
 failed:=false;begin perform public.memocious_builder_draft(sa,'save',did,1,2,8,jsonb_set(f,'{requestedDate}',to_jsonb(((now() at time zone 'Asia/Kolkata')::date+1)::text)));exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Lead time ignored';end if;
 failed:=false;begin perform public.memocious_builder_draft(sa,'save',did,1,2,8,jsonb_set(f,'{contact,name}','""'));exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Incomplete contact accepted';end if;
 failed:=false;begin perform public.memocious_builder_draft(sa,'save',did,1,2,8,f||'{"estimatePaise":1}');exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Client estimate accepted';end if;
 -- Older drafts upgrade explicitly without dropping the original message or version.
 perform public.memocious_builder_draft(sa,'create',old_id,0,1,1,legacy||'{"message":"Retained"}');
 r:=public.memocious_builder_draft(sa,'save',old_id,1,2,4,jsonb_set(f,'{message}','"Retained"'));
 if r->>'version'<>'2' or r->'payload'->>'message'<>'Retained' then raise exception 'Schema upgrade lost data';end if;
 failed:=false;begin perform public.memocious_builder_draft(sa,'save',old_id,2,1,1,legacy);exception when serialization_failure then failed:=true;end;if not failed then raise exception 'Old client overwrote schema 2';end if;
 execute 'reset role';update memocious.products set version=2,price_paise=500 where id=pid;execute 'set local role service_role';
 if public.memocious_builder_draft(sa,'read',did)->'estimate'->>'status'<>'changed' then raise exception 'Stale estimate not identified';end if;
 failed:=false;begin perform public.memocious_builder_draft(sa,'save',did,1,2,8,f);exception when serialization_failure then failed:=true;end;if not failed then raise exception 'Stale pricing saved';end if;
 f:=jsonb_set(f,'{pricingVersion}','2');perform public.memocious_builder_draft(sa,'save',did,1,2,8,f);
 execute 'reset role';update memocious.products set max_price_paise=null,version=3 where id=pid;execute 'set local role service_role';
 r:=public.memocious_builder_draft(sa,'save',did,2,2,8,jsonb_set(f,'{pricingVersion}','3'));
 if r->'estimate'->>'maxPaise' is not null then raise exception 'Invented upper bound';end if;
 execute 'reset role';update memocious.products set price_paise=null,version=4 where id=pid;execute 'set local role service_role';
 r:=public.memocious_builder_draft(sa,'save',did,3,2,8,jsonb_set(f,'{pricingVersion}','4'));
 if r->'estimate'->>'status'<>'quote' then raise exception 'Unknown base price invented';end if;
 execute 'reset role';insert into memocious.product_options(product_id,kind,label,required,max_count) values(pid,'upload','Required reference',true,1);execute 'set local role service_role';
 failed:=false;begin perform public.memocious_builder_draft(sa,'save',did,4,2,8,jsonb_set(f,'{pricingVersion}','4'));exception when invalid_parameter_value then failed:=true;end;if not failed then raise exception 'Required photo prerequisite bypassed';end if;
 execute 'reset role';
end $$;
rollback;
select 'PASS: compatible descendant choices, option/quantity price arithmetic, retry, required/duplicate/cross-type/MOQ/date/contact/price-injection denial, schema upgrade/old-client conflict, stale pricing, null upper bound and quote-only unknown price' as result;
